package dao; import dto.PostVideoDTO; import util.DBConnection; import java.sql.*; import java.util.*;
public class PostVideoDAO { public int insert(PostVideoDTO x)throws Exception{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO post_video(post_id,video_name,video_path,thumbnail_path,video_order) VALUES(?,?,?,?,?)")){p.setLong(1,x.getPostId());p.setString(2,x.getVideoName());p.setString(3,x.getVideoPath());p.setString(4,x.getThumbnailPath());p.setInt(5,x.getVideoOrder());return p.executeUpdate();}}
public List<PostVideoDTO> selectByPostId(long id)throws Exception{List<PostVideoDTO>a=new ArrayList<>();try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT * FROM post_video WHERE post_id=? ORDER BY video_order,video_id")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){while(r.next())a.add(map(r));}}return a;}
public PostVideoDTO selectById(long id)throws Exception{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT * FROM post_video WHERE video_id=?")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){return r.next()?map(r):null;}}} public int delete(long id)throws Exception{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("DELETE FROM post_video WHERE video_id=?")){p.setLong(1,id);return p.executeUpdate();}} public int getMaxOrder(long id)throws Exception{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT COALESCE(MAX(video_order),0) FROM post_video WHERE post_id=?")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){return r.next()?r.getInt(1):0;}}}
private PostVideoDTO map(ResultSet r)throws SQLException{PostVideoDTO x=new PostVideoDTO();x.setVideoId(r.getLong("video_id"));x.setPostId(r.getLong("post_id"));x.setVideoName(r.getString("video_name"));x.setVideoPath(r.getString("video_path"));x.setThumbnailPath(r.getString("thumbnail_path"));x.setVideoOrder(r.getInt("video_order"));x.setCreatedAt(r.getTimestamp("created_at"));return x;}}
